# -*- coding: utf-8 -*-
from lib import *
import re
U={k:CR[k]['url'] for k in CR}
def C(k,frag): 
    assert frag in CR[k]['text'],frag
    return QI(frag,U[k],k)
def lines(k):
    t=CR[k]['text']
    if k=='athanasian':
        parts=re.split(r'(?=\b\d{1,2}\) )',t.replace('\n\n',' '))
        return [p.strip() for p in parts if p.strip()]
    return [p.strip() for p in t.split('\n\n') if p.strip()]
def first(l):
    l=re.sub(r'^\d+\)\s*','',l)
    cl=[c for c in re.split(r'[，；。、！!：]',l) if c.strip()]
    return ''.join(c.strip()[0] for c in cl)
def reader(k,icon,sub):
    L=lines(k); USED.append(('CREED',k,U[k],CR[k]['text']))
    cls=''.join(f'<p class="cl">{(lambda m: f"<span class=n>{m[1]}</span>{esc(m[2])}" if m else esc(l))(re.match(r"^(\d+)\)\s*(.*)$",l,re.S))}</p>' for l in L)
    fl=''.join(f'<div>{esc(first(l))}</div>' for l in L)
    return (f'<div class="creedbox" id="r-{k}"><div class="rbar"><button type="button" data-m="mask">🙈 遮盖背诵（点句显示）</button><button type="button" data-m="first">🔤 首字提示</button><button type="button" data-m="big">🔍 放大</button><button type="button" data-m="small">🔎 缩小</button><button type="button" data-m="speak">🔊 朗读</button><button type="button" data-m="copy">📋 复制全文</button></div>'
            f'<div class="creed"><h3>{icon} {esc(CR[k]["title"])}</h3><div class="meta">{sub}<br>原文逐字取自：<a href="{U[k]}" target="_blank" rel="noopener">{U[k]}</a></div>{cls}<div class="fl">{fl}</div></div></div>')
